27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @Column(name = "household_id")
61	    private String householdId;
62	
63	    @Column(name = "namesake_count")
64	    private Integer namesakeCount;
65	
66	    /**
67	     * Whether this owner was one of a bulk signup for its registration day (more than
68	     * 80 owners created for that day). Derived at response time, never persisted.
69	     */
70	    @Transient
71	    private Boolean bulkSignupWarning;
72	
73	    /**
74	     * The number of owners sharing this owner's household (the same householdId),
75	     * counting this owner. Derived at response time from the persisted householdId,
76	     * never persisted. Drives the 'GOLD' membership tier (3 or more members).
77	     */
78	    @Transient
79	    private Integer householdSize;
80	
81	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
82	    private Set<Pet> pets;
83	
84	    public String getAddress() {
85	        return this.address;
86	    }
87	
88	    public void setAddress(String address) {
89	        this.address = address;
90	    }
91	
92	    public String getCity() {
93	        return this.city;
94	    }
95	
96	    public void setCity(String city) {
97	        this.city = city;
98	    }
99	
100	    public String getTelephone() {
101	        return this.telephone;
102	    }
103	
104	    public void setTelephone(String telephone) {
105	        this.telephone = telephone;
106	    }
107	
108	    public String getEmail() {
109	        return this.email;
110	    }
111	
112	    public void setEmail(String email) {
113	        this.email = email;
114	    }
115	
116	    public LocalDate getRegistrationDate() {
117	        return this.registrationDate;
118	    }
119	
120	    public void setRegistrationDate(LocalDate registrationDate) {
121	        this.registrationDate = registrationDate;
122	    }
123	
124	    public String getCustomerCode() {
125	        return this.customerCode;
126	    }
127	
128	    public void setCustomerCode(String customerCode) {
129	        this.customerCode = customerCode;
130	    }
131	
132	    public String getHouseholdId() {
133	        return this.householdId;
134	    }
135	
136	    public void setHouseholdId(String householdId) {
137	        this.householdId = householdId;
138	    }
139	
140	    public Integer getNamesakeCount() {
141	        return this.namesakeCount;
142	    }
143	
144	    public void setNamesakeCount(Integer namesakeCount) {
145	        this.namesakeCount = namesakeCount;
146	    }
147	
148	    public Boolean getBulkSignupWarning() {
149	        return this.bulkSignupWarning;
150	    }
151	
152	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
153	        this.bulkSignupWarning = bulkSignupWarning;
154	    }
155	
156	    public Integer getHouseholdSize() {
157	        return this.householdSize;
158	    }
159	
160	    public void setHouseholdSize(Integer householdSize) {
161	        this.householdSize = householdSize;
162	    }
163	
164	    protected Set<Pet> getPetsInternal() {
165	        if (this.pets == null) {
166	            this.pets = new HashSet<>();
167	        }
168	        return this.pets;
169	    }
170	
171	    protected void setPetsInternal(Set<Pet> pets) {
172	        this.pets = pets;
173	    }
174	
175	    public List<Pet> getPets() {
176	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
177	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
178	        return Collections.unmodifiableList(sortedPets);
179	    }
180	
181	    public void setPets(List<Pet> pets) {
182	        this.pets = new HashSet<>(pets);
183	    }
184	
185	    public void addPet(Pet pet) {
186	        getPetsInternal().add(pet);
187	        pet.setOwner(this);
188	    }
189	
190	    /**
191	     * Return the Pet with the given name, or null if none found for this Owner.
192	     *
193	     * @param name to test
194	     * @return true if pet name is already in use
195	     */
196	    public Pet getPet(String name) {
197	        return getPet(name, false);
198	    }
199	
200	    /**
201	     * Return the Pet with the given name, or null if none found for this Owner.
202	     *
203	     * @param name to test
204	     * @return true if pet name is already in use
205	     */
206	    public Pet getPet(String name, boolean ignoreNew) {
207	        name = name.toLowerCase();
208	        for (Pet pet : getPetsInternal()) {
209	            if (!ignoreNew || !pet.isNew()) {
210	                String compName = pet.getName();
211	                compName = compName.toLowerCase();
212	                if (compName.equals(name)) {
213	                    return pet;
214	                }
215	            }
216	        }
217	        return null;
218	    }
219	
220	    public Pet getPet(Integer petId) {
221	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
222	    }
223	
224	    @Override
225	    public String toString() {
226	        return new ToStringCreator(this)
227	
228	            .append("id", this.getId())
229	            .append("new", this.isNew())
230	            .append("lastName", this.getLastName())
231	            .append("firstName", this.getFirstName())
232	            .append("address", this.address)
233	            .append("city", this.city)
234	            .append("telephone", this.telephone)
235	            .toString();
236	    }
237	}
