     6	/**
     7	 * Normalizes an owner telephone number into E.164 form.
     8	 *
     9	 * <p>Rules: strip spaces, dashes and brackets. If a leading {@code '+'} (and therefore an
    10	 * explicit country code) is present it is kept as-is. Otherwise the default country code
    11	 * {@code +61} is assumed and a single leading {@code '0'} is dropped from the national digits.
    12	 * The result must carry 8 to 15 digits after the {@code '+'}. Anything that cannot form a
    13	 * valid E.164 number raises {@link InvalidOwnerTelephoneException} so the endpoint responds 400.
    14	 *
    15	 * <p>For recognised country codes the national number (the digits after the country code) must
    16	 * also have the exact length that country requires: {@code +61} (Australia) needs 9 national
    17	 * digits and {@code +1} (NANP) needs 10. A wrong national-number length raises
    18	 * {@link InvalidOwnerTelephoneException} so the endpoint responds 400.
    19	 *
    20	 * <p>So {@code "0412 345 678"} becomes {@code "+61412345678"} and {@code "+64 21 123 456"}
    21	 * becomes {@code "+6421123456"}.
    22	 */
    23	final class OwnerTelephone {
    24	
    25	    /** Default country code assumed when the input carries no explicit {@code '+'} prefix. */
    26	    private static final String DEFAULT_COUNTRY_CODE = "61";
    27	
    28	    private static final int MIN_DIGITS = 8;
    29	
    30	    private static final int MAX_DIGITS = 15;
    31	
    32	    /**
    33	     * National-number length required per country code. Ordered longest code first so the most
    34	     * specific prefix wins when matching.
    35	     */
    36	    private static final Map<String, Integer> NATIONAL_LENGTH = new LinkedHashMap<>();
    37	
    38	    static {
    39	        NATIONAL_LENGTH.put("61", 9); // Australia
    40	        NATIONAL_LENGTH.put("1", 10); // North American Numbering Plan
    41	    }
    42	
    43	    private OwnerTelephone() {
    44	    }
    45	
    46	    /**
    47	     * Convert a raw telephone string into E.164 form, or throw when it cannot form a valid one.
    48	     */
    49	    static String toE164(String raw) throws InvalidOwnerTelephoneException {
    50	        if (raw == null) {
    51	            throw new InvalidOwnerTelephoneException("null");
    52	        }
    53	        // Strip spaces, dashes and brackets.
    54	        String cleaned = raw.replaceAll("[\\s()\\[\\]-]", "");
    55	        boolean explicitCountryCode = cleaned.startsWith("+");
    56	        String digits = explicitCountryCode ? cleaned.substring(1) : cleaned;
    57	        if (digits.isEmpty() || !digits.chars().allMatch(Character::isDigit)) {
    58	            throw new InvalidOwnerTelephoneException(raw);
    59	        }
    60	        String e164Digits;
    61	        if (explicitCountryCode) {
    62	            e164Digits = digits;
    63	        }
    64	        else {
    65	            // No explicit country code: assume the default and drop one leading national '0'.
    66	            String national = digits.startsWith("0") ? digits.substring(1) : digits;
    67	            e164Digits = DEFAULT_COUNTRY_CODE + national;
    68	        }
    69	        if (e164Digits.length() < MIN_DIGITS || e164Digits.length() > MAX_DIGITS) {
    70	            throw new InvalidOwnerTelephoneException(raw);
    71	        }
    72	        // For a recognised country code, the national number must have the exact required length.
    73	        for (Map.Entry<String, Integer> entry : NATIONAL_LENGTH.entrySet()) {
    74	            String countryCode = entry.getKey();
    75	            if (e164Digits.startsWith(countryCode)) {
    76	                int national = e164Digits.length() - countryCode.length();
    77	                if (national != entry.getValue()) {
    78	                    throw new InvalidOwnerTelephoneException(raw);
    79	                }
    80	                break;
    81	            }
    82	        }
    83	        return "+" + e164Digits;
    84	    }
    85	
    86	    /**
    87	     * Canonical E.164 form for comparison, falling back to a digits-only form for values that
    88	     * cannot form a valid E.164 number (e.g. legacy data).
    89	     */
    90	    static String canonical(String raw) {
    91	        try {
    92	            return toE164(raw);
    93	        }
    94	        catch (InvalidOwnerTelephoneException ex) {
    95	            return raw == null ? "" : raw.replaceAll("\\D", "");
    96	        }
    97	    }
    98	}

