     6	/**
     7	 * Rolls a date forward onto a business day. The registration date of an owner must
     8	 * fall on a business day: a Saturday or Sunday is rolled forward to the following
     9	 * Monday. Any value derived from the registration date (e.g. the membership number's
    10	 * year segment) therefore uses the adjusted date.
    11	 */
    12	public final class BusinessDays {
    13	
    14	    private BusinessDays() {
    15	    }
    16	
    17	    /**
    18	     * Adjust a date onto a business day: when it falls on a weekend, roll it forward to
    19	     * the next Monday; otherwise return it unchanged.
    20	     */
    21	    public static LocalDate adjust(LocalDate date) {
    22	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
    23	            date = date.plusDays(1);
    24	        }
    25	        return date;
    26	    }
    27	}

